CREATE TABLE IF NOT EXISTS public.system_settings (key text PRIMARY KEY, value jsonb NOT NULL, description text, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid);
GRANT SELECT ON public.system_settings TO authenticated;
GRANT ALL ON public.system_settings TO service_role;
ALTER TABLE public.system_settings ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX IF NOT EXISTS collaborators_user_id_unique ON public.collaborators(user_id) WHERE user_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT auth.uid() IS NOT NULL AND public.has_role(auth.uid(), 'admin'::public.app_role); $$;
CREATE OR REPLACE FUNCTION public.is_auth_enforced() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT coalesce((SELECT (value #>> '{}')::boolean FROM public.system_settings WHERE key='auth_enforced'),false); $$;
CREATE OR REPLACE FUNCTION public.current_collaborator_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT id FROM public.collaborators WHERE user_id=auth.uid() AND is_active=true LIMIT 1; $$;
CREATE OR REPLACE FUNCTION public.bootstrap_current_profile() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE current_user_id uuid := auth.uid(); current_email text; matched_collaborator public.collaborators%ROWTYPE; BEGIN IF current_user_id IS NULL THEN RAISE EXCEPTION 'authentication_required'; END IF; SELECT lower(email) INTO current_email FROM auth.users WHERE id=current_user_id AND email_confirmed_at IS NOT NULL; SELECT * INTO matched_collaborator FROM public.collaborators WHERE is_active AND (user_id=current_user_id OR (user_id IS NULL AND email IS NOT NULL AND lower(email)=current_email)) ORDER BY (user_id=current_user_id) DESC NULLS LAST LIMIT 1 FOR UPDATE; IF matched_collaborator.id IS NULL THEN RAISE EXCEPTION 'active_linked_collaborator_required'; END IF; IF matched_collaborator.user_id IS NULL THEN UPDATE public.collaborators SET user_id=current_user_id WHERE id=matched_collaborator.id AND user_id IS NULL; END IF; INSERT INTO public.profiles(user_id,display_name,collaborator_id) VALUES(current_user_id,matched_collaborator.name,matched_collaborator.id) ON CONFLICT(user_id) DO UPDATE SET collaborator_id=excluded.collaborator_id,updated_at=now(); INSERT INTO public.user_roles(user_id,role) VALUES(current_user_id,'user'::public.app_role) ON CONFLICT(user_id,role) DO NOTHING; RETURN matched_collaborator.id; END; $$;
CREATE OR REPLACE FUNCTION public.set_auth_enforced(p_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'admin_role_required'; END IF; INSERT INTO public.system_settings(key,value,description,updated_by) VALUES('auth_enforced',to_jsonb(p_enabled),'Authentication cutover for Plano Mestre',auth.uid()) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=now(),updated_by=auth.uid(); END; $$;
CREATE POLICY system_settings_admin_read ON public.system_settings FOR SELECT TO authenticated USING(public.is_admin());
REVOKE ALL ON FUNCTION public.is_admin(),public.current_collaborator_id(),public.bootstrap_current_profile(),public.set_auth_enforced(boolean) FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.is_auth_enforced() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_admin(),public.current_collaborator_id(),public.bootstrap_current_profile(),public.set_auth_enforced(boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.is_auth_enforced() TO anon,authenticated;
COMMENT ON TABLE public.system_settings IS 'Plano Mestre authentication preparation; existing operational anonymous grants and policies preserved.';